// ---- Settings ---------------------------------------------------------------
const CONFIG = {
  llmProvider: 'openai',   // 'openai' (credential "OpenAI account") or 'ollama' (local, no data leaves the server)
  llmModel: 'gpt-4o-mini', // for Ollama use e.g. 'qwen2.5:7b'
  ollamaUrl: 'http://ollama:11434',
  maxChars: 3500,          // text per LLM call
  defaultMaxChunks: 40,    // chunks read per request unless "maxChunks" is sent
};
// The portal's document requirements (keep in sync with packages/shared/src/reference.ts).
const REQUIREMENTS = {
  'application-form': 'Application form fields', artwork: 'Label or artwork',
  cover: 'Cover letter', poa: 'Power of attorney', ltrletter: 'Letter appointing the local technical representative', tm: 'Trademark agreement',
  sameness: 'Declaration of sameness', 'rra-gmp': 'GMP certificate issued by the reference regulatory authority',
  'rra-auth': 'Letter of authorization for the reference regulatory authority to share information with Rwanda FDA',
  m1: 'CTD Module 1: Administrative and prescribing information', m2: 'CTD Module 2: Summaries', m3: 'CTD Module 3: Quality',
  m4: 'CTD Module 4: Non-clinical study reports', m5: 'CTD Module 5: Clinical studies', other: 'Other documents',
  gmp: 'GMP certificate', coa: 'Certificate of analysis', spc: 'Summary of product characteristics', wd: 'Withdrawal period justification',
  fsc: 'Food safety certificate', comp: 'Product composition', fsale: 'Free sale certificate', inci: 'Ingredient list (INCI)',
  safety: 'Product safety assessment', iso: 'ISO 13485 certificate', doc: 'Declaration of conformity', tech: 'Technical file summary', ifu: 'Instructions for use',
};
// -----------------------------------------------------------------------------
const body = $input.first().json.body || {};
const sourceKey = String(body.sourceKey || '').trim().toLowerCase();
const maxChunks = Math.min(500, Math.max(1, parseInt(body.maxChunks, 10) || CONFIG.defaultMaxChunks));
const errors = [];
if (!/^[a-z0-9][a-z0-9_.-]{1,80}$/.test(sourceKey)) errors.push('sourceKey is required: the id used when the document was uploaded');
return [{ json: { valid: !errors.length, errors, sourceKey, maxChunks, config: CONFIG, requirements: REQUIREMENTS } }];

// Group the document's chunks into LLM-sized batches. The first row tells us whether the document exists.
const req = $('Validate request').first().json;
const rows = $input.all().map((i) => i.json).filter((r) => r && r.document_id);
if (!rows.length) return [{ json: { found: false } }];

const doc = { id: Number(rows[0].document_id), title: rows[0].title, kind: rows[0].kind, productTypes: rows[0].product_types || [], requirementIds: rows[0].requirement_ids || [] };
const batches = [];
let cur = null;
for (const r of rows.slice(0, req.maxChunks)) {
  if (!cur || cur.text.length + r.content.length > req.config.maxChars) { cur = { text: '', pages: new Set() }; batches.push(cur); }
  cur.text += (cur.text ? '\n\n' : '') + r.content;
  if (r.page) cur.pages.add(r.page);
}
return batches.map((b, i) => ({ json: { found: true, doc, batch: i + 1, of: batches.length, pages: [...b.pages], text: b.text, chunksRead: Math.min(rows.length, req.maxChunks), chunksTotal: rows.length } }));

// LLM request and response helpers, shared by every node that talks to the model.
// OpenAI uses strict JSON-schema output; Ollama uses its "format" option.
function strictSchema(s) {
  // OpenAI strict mode: every object lists all its properties as required and allows no others.
  if (s && s.type === 'object') return { ...s, additionalProperties: false, required: Object.keys(s.properties), properties: Object.fromEntries(Object.entries(s.properties).map(([k, v]) => [k, strictSchema(v)])) };
  if (s && s.type === 'array') return { ...s, items: strictSchema(s.items) };
  return s;
}
function llmRequest(config, system, user, schema, name) {
  const messages = [{ role: 'system', content: system }, { role: 'user', content: user }];
  if (config.llmProvider === 'openai') {
    return { model: config.llmModel, temperature: 0, messages, response_format: { type: 'json_schema', json_schema: { name, strict: true, schema: strictSchema(schema) } } };
  }
  return { model: config.llmModel, stream: false, format: schema, options: { temperature: 0, num_ctx: 8192 }, messages };
}
// Returns { data, error, tokens } from either provider's response item.
function llmResult(json) {
  if (json.error) return { data: null, error: String(json.error.message || json.error), tokens: 0 };
  const content = json.choices ? json.choices[0] && json.choices[0].message && json.choices[0].message.content : json.message && json.message.content;
  const tokens = json.usage ? json.usage.total_tokens || 0 : (json.prompt_eval_count || 0) + (json.eval_count || 0);
  try { return { data: JSON.parse(content || ''), error: null, tokens }; } catch (e) { return { data: null, error: 'Invalid JSON from the model', tokens }; }
}

const req = $('Validate request').first().json;
const allowed = Object.entries(req.requirements).map(([id, name]) => `- ${id}: ${name}`).join('\n');

const schema = {
  type: 'object',
  properties: {
    rules: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          text: { type: 'string' },
          severity: { type: 'string', enum: ['critical', 'major', 'minor'] },
          guidance: { type: 'string' },
          requirementIds: { type: 'array', items: { type: 'string' } },
          quote: { type: 'string' },
        },
        required: ['text', 'severity', 'guidance', 'requirementIds', 'quote'],
      },
    },
  },
  required: ['rules'],
};

const common = `Each rule must be ONE checkable statement that a reviewer can mark pass or fail by reading the applicant's documents. Split compound requirements into separate rules.
severity: "critical" for identity, safety or legal validity; "major" for content the dossier must have; "minor" for presentation.
guidance: one sentence telling the reviewer what is acceptable and what is not, or an empty string.
requirementIds: the documents where the reviewer should look, chosen ONLY from this list (empty list = the whole dossier):
${allowed}
quote: the sentence from the excerpt the rule comes from, copied word for word, at most 30 words.
Only use what the excerpt says. If it contains no requirement, return {"rules": []}. Respond with JSON only.`;

const system = {
  guideline: `You turn regulatory guidance into review rules for Rwanda FDA product registration.\nWrite each rule as a statement about the submission, e.g. "The label states the storage temperature."\n${common}`,
  template: `The excerpt is a TEMPLATE that applicants must follow. List the mandatory sections, fields and statements a completed document must contain.\nWrite each rule as "The <document> contains <section, field or statement>."\n${common}`,
  reference: `You turn regulatory reference material into review rules for Rwanda FDA product registration.\n${common}`,
};

return $input.all().map((item) => {
  const b = item.json;
  const scope = b.doc.requirementIds.length ? `This document applies to: ${b.doc.requirementIds.map((id) => req.requirements[id] || id).join('; ')}.` : '';
  return {
    json: {
      ...b,
      request: llmRequest(req.config, system[b.doc.kind] || system.guideline, `DOCUMENT: ${b.doc.title} (${b.doc.kind})\n${scope}\n\nEXCERPT:\n${b.text}`, schema, 'proposed_rules'),
    },
  };
});

// LLM request and response helpers, shared by every node that talks to the model.
// OpenAI uses strict JSON-schema output; Ollama uses its "format" option.
function strictSchema(s) {
  // OpenAI strict mode: every object lists all its properties as required and allows no others.
  if (s && s.type === 'object') return { ...s, additionalProperties: false, required: Object.keys(s.properties), properties: Object.fromEntries(Object.entries(s.properties).map(([k, v]) => [k, strictSchema(v)])) };
  if (s && s.type === 'array') return { ...s, items: strictSchema(s.items) };
  return s;
}
function llmRequest(config, system, user, schema, name) {
  const messages = [{ role: 'system', content: system }, { role: 'user', content: user }];
  if (config.llmProvider === 'openai') {
    return { model: config.llmModel, temperature: 0, messages, response_format: { type: 'json_schema', json_schema: { name, strict: true, schema: strictSchema(schema) } } };
  }
  return { model: config.llmModel, stream: false, format: schema, options: { temperature: 0, num_ctx: 8192 }, messages };
}
// Returns { data, error, tokens } from either provider's response item.
function llmResult(json) {
  if (json.error) return { data: null, error: String(json.error.message || json.error), tokens: 0 };
  const content = json.choices ? json.choices[0] && json.choices[0].message && json.choices[0].message.content : json.message && json.message.content;
  const tokens = json.usage ? json.usage.total_tokens || 0 : (json.prompt_eval_count || 0) + (json.eval_count || 0);
  try { return { data: JSON.parse(content || ''), error: null, tokens }; } catch (e) { return { data: null, error: 'Invalid JSON from the model', tokens }; }
}

// Keep only rules whose quote really is in the excerpt, then store them as "proposed".
const req = $('Validate request').first().json;
const batches = $('Build prompts').all().map((i) => i.json);
// Words and numbers only, so small punctuation differences in the model's quote don't drop a good proposal.
const norm = (s) => String(s || '').toLowerCase().normalize('NFKD').replace(/[^a-z0-9]+/g, ' ').trim();
const esc = (s) => "'" + String(s).replace(/\u0000/g, '').replace(/'/g, "''") + "'";
const arr = (a) => `ARRAY[${a.map(esc).join(',')}]::text[]`;
// Short stable hash so the same proposal from a re-run gets the same code (and is not duplicated).
const hash = (s) => { let h = 2166136261; for (const c of s) { h ^= c.charCodeAt(0); h = Math.imul(h, 16777619); } return (h >>> 0).toString(36).toUpperCase().padStart(6, '0').slice(-6); };

const doc = batches[0].doc;
const kept = [], dropped = [];
$input.all().forEach((item, i) => {
  const b = batches[i];
  const res = llmResult(item.json);
  if (!res.data) dropped.push({ text: `(batch ${b.batch})`, reason: res.error });
  const out = res.data;
  for (const r of (out && Array.isArray(out.rules) ? out.rules : [])) {
    const text = String(r.text || '').trim();
    const severity = ['critical', 'major', 'minor'].includes(r.severity) ? r.severity : null;
    if (text.length < 10 || text.length > 500 || !severity) { dropped.push({ text, reason: 'incomplete' }); continue; }
    if (!norm(r.quote) || !norm(b.text).includes(norm(r.quote))) { dropped.push({ text, reason: 'quote not found in the document' }); continue; }
    let ids = (Array.isArray(r.requirementIds) ? r.requirementIds : []).map(String).filter((id) => req.requirements[id]);
    if (!ids.length) ids = doc.requirementIds;
    const where = b.pages.length ? `, page ${b.pages.join('/')}` : '';
    const guidance = [String(r.guidance || '').trim(), `Proposed from "${doc.title}"${where}: "${String(r.quote).trim()}"`].filter(Boolean).join(' ');
    kept.push({ code: `P${doc.id}-${hash(norm(text))}`, text, severity, guidance, requirementIds: ids });
  }
});
const callErrors = dropped.filter((d) => d.text.startsWith('(batch '));
if (callErrors.length === batches.length) throw new Error(`Every LLM call failed. First error: ${callErrors[0].reason}`);
const unique = [...new Map(kept.map((r) => [r.code, r])).values()];
const sql = unique.length
  ? `INSERT INTO guideline_rules (rule_code, rule_text, severity, guidance, product_types, requirement_ids, status, source_document_id)
VALUES ${unique.map((r) => `(${esc(r.code)}, ${esc(r.text)}, ${esc(r.severity)}, ${esc(r.guidance)}, ${arr(doc.productTypes)}, ${arr(r.requirementIds)}, 'proposed', ${doc.id})`).join(',\n')}
ON CONFLICT (rule_code) DO NOTHING RETURNING rule_code;`
  : 'SELECT NULL AS rule_code WHERE false;';
return [{ json: { sql, proposed: unique.length, dropped } }];
